// קריאת נתוני ג'ויסטיק אנלוגיים:
const int joyXPin = 34; // או A0 בארדואינו
const int joyYPin = 35; // או A1

void setup() {
  Serial.begin(115200);
}

void loop() {
  int xVal = analogRead(joyXPin);
  int yVal = analogRead(joyYPin);
  Serial.print("Joy X: "); Serial.print(xVal);
  Serial.print(" | Joy Y: "); Serial.println(yVal);
  delay(100);
}

