#include <ESP32Servo.h>

Servo baseServo;
const int joyXPin = 34;

void setup() {
  baseServo.attach(18);
}

void loop() {
  int xVal = analogRead(joyXPin);
  int angle = map(xVal, 0, 4095, 0, 180);
  baseServo.write(angle);
  delay(15);
}

