// שגרת Pick and Place אוטונומית:
void performPickAndPlace() {
  // 1. פתיחת גריפר
  gripper.write(10); delay(500);
  // 2. ירידה לחפץ
  shoulder.write(45); elbow.write(120); delay(800);
  // 3. סגירת גריפר
  gripper.write(75); delay(600);
  // 4. הרמה
  shoulder.write(90); elbow.write(90); delay(700);
  // 5. סיבוב ימינה
  base.write(150); delay(800);
  // 6. הנחה
  gripper.write(10); delay(500);
  // 7. חזרה למרכז
  base.write(90);
}

void setup() {}
void loop() {
  performPickAndPlace();
  while(1); // עצירה בסיום
}

