#include <ESP32Servo.h>

Servo armServo;
int currentAngle = 90;

void setup() {
  armServo.attach(19);
  armServo.write(currentAngle);
}

void loop() {
  int yVal = analogRead(35);
  if (yVal > 2500 && currentAngle < 170) currentAngle += 2;
  if (yVal < 1500 && currentAngle > 10) currentAngle -= 2;
  armServo.write(currentAngle);
  delay(20);
}

