lessons.codeTemplate:
#include <ESP32Servo.h>

Servo gripperServo;
const int buttonPin = 23;
bool isOpen = true;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  gripperServo.attach(5);
  gripperServo.write(10); // פתוח
}

void loop() {
  if (digitalRead(buttonPin) == LOW) {
    isOpen = !isOpen;
    gripperServo.write(isOpen ? 10 : 75);
    delay(300);
  }
}

