// אלגוריתם אוטונומי מלא:
void loop() {
  if (bot.getDistance() < 25) {
    bot.stop();
    int rightDist = bot.scanRight();
    int leftDist = bot.scanLeft();
    if (rightDist > leftDist) {
      bot.turnRight(200);
    } else {
      bot.turnLeft(200);
    }
  } else {
    bot.moveForward(180);
  }
}

